create extension if not exists "uuid-ossp";
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, avatar_url text, created_at timestamptz not null default now());
create table public.workspaces (id uuid primary key default uuid_generate_v4(), name text not null, owner_id uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table public.workspace_members (workspace_id uuid references public.workspaces(id) on delete cascade, user_id uuid references auth.users(id) on delete cascade, role text not null default 'member' check (role in ('owner','member')), primary key (workspace_id,user_id));
create table public.accounts (id uuid primary key default uuid_generate_v4(), workspace_id uuid not null references public.workspaces(id) on delete cascade, name text not null, institution text, account_type text not null default 'checking', balance numeric(12,2) not null default 0, last_synced_at timestamptz);
create table public.transactions (id uuid primary key default uuid_generate_v4(), workspace_id uuid references public.workspaces(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, account_id uuid references public.accounts(id) on delete set null, merchant text not null, category text not null, amount numeric(12,2) not null, date date not null default current_date, status text not null default 'cleared' check (status in ('cleared','pending')), notes text, created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.workspaces enable row level security; alter table public.workspace_members enable row level security; alter table public.accounts enable row level security; alter table public.transactions enable row level security;
create policy "profiles own" on public.profiles for all using (id = auth.uid()) with check (id = auth.uid());
create policy "members see workspaces" on public.workspaces for select using (owner_id = auth.uid() or exists (select 1 from public.workspace_members m where m.workspace_id=id and m.user_id=auth.uid()));
create policy "owners manage workspaces" on public.workspaces for all using (owner_id = auth.uid()) with check (owner_id = auth.uid());
create policy "members manage membership" on public.workspace_members for all using (user_id = auth.uid() or exists (select 1 from public.workspaces w where w.id=workspace_id and w.owner_id=auth.uid()));
create policy "workspace accounts" on public.accounts for all using (exists (select 1 from public.workspace_members m where m.workspace_id=workspace_id and m.user_id=auth.uid()) or exists (select 1 from public.workspaces w where w.id=workspace_id and w.owner_id=auth.uid()));
create policy "user transactions" on public.transactions for all using (user_id=auth.uid() or exists (select 1 from public.workspace_members m where m.workspace_id=workspace_id and m.user_id=auth.uid()));
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles(id, full_name) values (new.id, coalesce(new.raw_user_meta_data->>'full_name', new.email)); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
